nb=RaatPaden.bouw; m=Sketchup.active_model; ents=m.entities; m.start_operation('Labels als 3D-tekst', true); tm=m.materials['Raat tekst'] || m.materials.add('Raat tekst'); tm.color=Sketchup::Color.new(45,45,50); lab=->(s,x,y,h){ g=ents.add_group; g.entities.add_3d_text(s, TextAlignLeft, 'Arial', false, false, h.m, 0.0, 0.0, true, 0.0); g.material=tm; g.transform!(Geom::Transformation.translation([x.m, y.m, 0])); g }; ents.grep(Sketchup::Text).each(&:erase!); ents.grep(Sketchup::Group).select{|g| g.material==tm}.each(&:erase!); ents.grep(Sketchup::ComponentInstance).select{|i| i.definition.description.start_with?('Raatstad padblok')}.each{|i| o=i.transformation.origin; lab.(i.definition.name, o.x.to_m-7.5, o.y.to_m-11.5, 0.9)}; ents.grep(Sketchup::ComponentInstance).select{|i| i.bounds.center.y.to_m < -125 && !i.definition.description.start_with?('Raatstad padblok')}.each(&:erase!); volg=%w[Pad Plein Plateau Helling Trap Brug Vloer Blok Vulstuk Pilaren Toren Raster Gebouw Vak Deel]; defs=m.definitions.reject{|d| d.image? || d.description.start_with?('Raatstad padblok') || d.name=~/^(Hulp|Schaalfiguur)/ || !volg.include?(d.name.split(' ').first)}; y=-150.0; n=0; lab.("Uit het concept (bergfort): #{defs.size} modules", -30, y+14, 3.0); volg.each{|cat| rij=defs.select{|d| d.name.split(' ').first==cat}.sort_by(&:name); next if rij.empty?; hmax=rij.map{|d| d.bounds.height.to_m}.max; x=0.0; lab.(cat, -30, y, 2.0); rij.each{|d| b=d.bounds; ents.add_instance(d, Geom::Transformation.translation([x.m-b.min.x, y.m-b.center.y, -b.min.z])); g=lab.(d.name.sub(/^\S+ · /,''), x, y-hmax/2-2.2, 0.9); w=[b.width.to_m, g.bounds.width.to_m].max; x+=w+5; n+=1}; y-=hmax+12}; m.commit_operation; m.definitions.purge_unused; m.active_view.zoom_extents; m.save(m.path); puts "labels klaar, modules: #{n}"; require 'json'; m=Sketchup.active_model; volg=%w[Pad Plein Plateau Helling Trap Brug Vloer Blok Vulstuk Pilaren Toren Raster Gebouw Vak Deel Steeg Tunnel Vlonder Fietspad Tuin]; r=->(v){ (v.to_m*100).round/100.0 }; kl=->(mat){ mat ? (c=mat.color; '#%02x%02x%02x' % [c.red,c.green,c.blue]) : nil }; walk=nil; walk=->(ents,t,mat,top,pts){ ents.each{|e|; if e.is_a?(Sketchup::Face) then ma=e.material||mat; n=e.normal.transform(t); e.outer_loop.vertices.each{|v| p=v.position.transform(t); pts << [r.(p.x),r.(p.y),r.(p.z)]}; if n.z>0.2 then top << {'p'=>e.outer_loop.vertices.map{|v| p=v.position.transform(t); [r.(p.x),r.(p.y),r.(p.z)]}, 'c'=>kl.(ma)} end; elsif e.is_a?(Sketchup::Group)||e.is_a?(Sketchup::ComponentInstance) then walk.(e.definition.entities, t*e.transformation, e.material||mat, top, pts) end }}; out=[]; m.definitions.each{|d| next if d.image? || d.name=~/^(Hulp|Schaalfiguur)/; cat=d.name.split(' ').first; next unless volg.include?(cat); top=[]; pts=[]; walk.(d.entities, Geom::Transformation.new, nil, top, pts); b=d.bounds; out << {'naam'=>d.name, 'soort'=>cat, 'bron'=>(d.description.start_with?('Raatstad padblok') ? 'nieuw' : 'concept'), 'groep'=>d.group?, 'bb'=>[r.(b.min.x),r.(b.min.y),r.(b.min.z),r.(b.max.x),r.(b.max.y),r.(b.max.z)], 'boven'=>top, 'punten'=>pts.uniq}}; f='G:/Mijn Drive/Projecten/hexgrid city concept/raatstad-modules.json'; File.write(f, JSON.generate({'bestand'=>m.path, 'modules'=>out})); puts "export: #{out.size} modules, #{File.size(f)} bytes"